import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Gli enti fondamentali","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/f_geometria-del-piano-euclideo/fb/fba.md","filePath":"lezioni/f_geometria-del-piano-euclideo/fb/fba.md"}`),a={name:`lezioni/f_geometria-del-piano-euclideo/fb/fba.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="gli-enti-fondamentali" tabindex="-1">Gli enti fondamentali <a class="header-anchor" href="#gli-enti-fondamentali" aria-label="Permalink to “Gli enti fondamentali”">​</a></h1><p>Dobbiamo fissare gli oggetti che saranno i protagonisti della nostra rappresentazione geometrica:</p><ul><li class="text-red">[Il punto]</li><li class="text-red">[La retta]</li><li class="text-red">[Il piano]</li></ul><p>fissare e non definire, infatti essi saranno gli indefinibili della geometria, nel senso che il mio concetto di punto deve essere uguale al tuo, però non posso definire il concetto di punto (concetto primitivo).</p><blockquote><p>Se ci pensi un po&#39; non è possibile definire il concetto di punto, infatti se disegni un puntino e lo guardi al microscopio cosa succede? Se pensi ad uno spazio inferiore al diametro di un atomo puoi ancora pensare il concetto di punto come qualcosa di ancora più piccolo?</p></blockquote>`,5)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};